#!/usr/bin/env python3
# Aplica los cambios de revision semana pagada a api/servicios/admin-semanas-pagadas.js
# Uso: python3 aplicar_parche_semanas_pagadas.py  (desde la raiz del repo, ~/workspace)
# Hace backup en .bak. Busca cada cambio por su texto exacto, no por numero de linea.
# Si un cambio no se encuentra, NO toca el archivo y te dice cual es.
import base64, json, pathlib, sys
RUTA = pathlib.Path('api/servicios/admin-semanas-pagadas.js')
EDITS = json.loads(base64.b64decode('').decode())
def main():
    if not RUTA.exists():
        print('No encontre', RUTA, '- corre el script desde la raiz del repo (~/workspace).')
        return 1
    texto = RUTA.read_text()
    original = texto
    for nombre, viejo, nuevo in EDITS:
        c = texto.count(viejo)
        if c != 1:
            print(f'{nombre}: NO se aplico - se encontro {c} veces (esperaba 1).')
            print('Tu archivo en Replit difiere del del zip en esa zona. No se modifico nada.')
            return 1
        texto = texto.replace(viejo, nuevo)
        print(f'{nombre}: ok')
    RUTA.with_suffix('.js.bak').write_text(original)
    RUTA.write_text(texto)
    print('Listo. Backup en api/servicios/admin-semanas-pagadas.js.bak')
    return 0
if __name__ == '__main__':
    raise SystemExit(main())
